#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# Fresh-Mac wizard: the steps chezmoi apply can't do (sign-ins, licences, system
# extensions, privacy permissions, Rex). Run after the first `chezmoi apply`:
#   ~/.local/share/chezmoi/scripts/wizard-mac.sh
# Every stage checks first and says so when it's already done, so a re-run is safe.

[[ "$(uname -s)" == "Darwin" ]] || { echo "This wizard is for macOS. On Windows: scripts/wizard-windows.ps1" >&2; exit 1; }
export PATH="$HOME/.local/bin:$HOME/.local/share/mise/shims:$PATH"

have_app()   { compgen -G "/Applications/$1" >/dev/null; }
launch_app() { open -a "$1" 2>/dev/null || warn "couldn't open $1; is it installed? (rerun chezmoi apply)"; }
PRIVACY="x-apple.systempreferences:com.apple.preference.security"

# Machine type from chezmoi's data; personal stages are skipped on work Macs.
IS_PERSONAL=$(chezmoi data --format json 2>/dev/null | jq -r '.is_personal // empty' 2>/dev/null || true)
if [[ "$IS_PERSONAL" != "true" && "$IS_PERSONAL" != "false" ]]; then
  if confirm "Is this a personal Mac? (No = work Mac)"; then IS_PERSONAL=true; else IS_PERSONAL=false; fi
fi

if [[ "$IS_PERSONAL" == "true" ]]; then TOTAL_STAGES=11; else TOTAL_STAGES=6; fi
banner "Fresh Mac: manual steps ($([[ "$IS_PERSONAL" == "true" ]] && echo personal || echo work) Mac)"

# ── Rex ──────────────────────────────────────────────────────────────────────
stage "Rex"
if have_app "Rex*.app"; then
  say "Rex is installed. Nothing to do."
else
  say "Rex is a closed beta: its install command is deliberately not in this public repo."
  step "Install Rex the way your beta invite describes."
  step "Open it once and sign in. Hyper+Enter opens it from then on."
fi
pause

if [[ "$IS_PERSONAL" == "true" ]]; then
# ── App Store ────────────────────────────────────────────────────────────────
stage "App Store sign-in and App Store apps"
say "mas can only install once you're signed in to the App Store."
launch_app "App Store"
step "App Store → Account (bottom left) → sign in with your Apple Account."
pause "Signed in? Press Enter to install Shapr3D, WhatsApp, Telegram and LocalSend."
for entry in "1091675654:Shapr3D" "310633997:WhatsApp" "747648890:Telegram" "1661733229:LocalSend"; do
  id="${entry%%:*}"; name="${entry#*:}"
  if have_app "$name.app"; then note "$name: already installed"; continue; fi
  if mas get "$id" >/dev/null 2>&1 || mas install "$id" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$name"
  else
    SKIPPED+=("$name from the App Store (mas get $id)"); warn "$name didn't install; get it from the App Store"
  fi
done
pause

# ── 1Password ────────────────────────────────────────────────────────────────
stage "1Password and its CLI"
launch_app "1Password"
step "Sign in to your 1Password account."
step "Settings → Developer → turn on 'Integrate with 1Password CLI'."
step "Settings → Developer → turn on 'Use the SSH agent' (git signing and SSH use it)."
pause "Done? Press Enter to check the CLI."
if op whoami >/dev/null 2>&1 || op account list 2>/dev/null | grep -q .; then
  printf '  %s✓%s op can reach 1Password\n' "$GREEN" "$RESET"
else
  SKIPPED+=("1Password CLI integration (Settings → Developer)"); warn "op can't reach 1Password yet; check the Developer settings"
fi
pause

# ── Tailscale ────────────────────────────────────────────────────────────────
stage "Tailscale"
launch_app "Tailscale"
step "Follow the onboarding: allow the system extension and the VPN configuration."
step "If macOS blocks the extension: Privacy & Security → allow 'Tailscale'."
step "Sign in to your tailnet."
pause

# ── Little Snitch ────────────────────────────────────────────────────────────
stage "Little Snitch"
launch_app "Little Snitch"
step "Agree to the licence and accept the network filter."
step "Click 'Open System Settings' (not the default button) and Allow the system extension."
open_url "$PRIVACY?Security"
step "Enter your licence key in Little Snitch, or keep the trial."
pause

# ── Affinity ─────────────────────────────────────────────────────────────────
stage "Affinity"
if have_app "Affinity*.app"; then
  say "Affinity is installed. Nothing to do."
else
  say "Affinity downloads only after a Canva sign-in, so the script can't fetch it."
  open_url "https://www.affinity.studio/get-affinity"
  step "Sign in with Canva, download Affinity for Mac, drag it to Applications."
fi
pause
fi

# ── Licences ─────────────────────────────────────────────────────────────────
stage "Licences and sign-ins"
say "Each app opens in turn. Enter its licence (from your password manager) or sign in."
LICENCED=("Alfred 5:Preferences → Powerpack → Activate" "Bartender 7:Settings → License" \
  "CleanShot X:Settings → General → License" "Swish:Settings → License" \
  "superwhisper:sign in to your account" "AlDente:Settings → Pro (upgrades the app in place)")
[[ "$IS_PERSONAL" == "true" ]] && LICENCED+=("iStat Menus:Settings → License")
for entry in "${LICENCED[@]}"; do
  app="${entry%%:*}"; where="${entry#*:}"
  if ! have_app "$app.app"; then SKIPPED+=("$app isn't installed (rerun chezmoi apply)"); warn "$app isn't installed"; continue; fi
  launch_app "$app"
  step "$app: $where"
  pause "Done with $app? Press Enter for the next one."
done

# ── Permissions ──────────────────────────────────────────────────────────────
stage "Privacy permissions"
say "These apps need Accessibility, and some Screen Recording. Launching each one"
say "triggers its prompt; grant them here in one go."
for app in AeroSpace DockDoor LinearMouse; do have_app "$app.app" && launch_app "$app"; done
open_url "$PRIVACY?Privacy_Accessibility"
step "Accessibility: turn on AeroSpace, Alfred 5, Bartender 7, DockDoor, LinearMouse, Swish, superwhisper, CleanShot X."
pause "Done? Press Enter for Screen Recording."
open_url "$PRIVACY?Privacy_ScreenCapture"
step "Screen & System Audio Recording: turn on Bartender 7, CleanShot X, DockDoor."
note "superwhisper asks for the microphone on first dictation."
pause

# ── Ollama ───────────────────────────────────────────────────────────────────
stage "Ollama command line"
if command -v ollama >/dev/null 2>&1; then
  say "ollama is on PATH. Nothing to do."
else
  launch_app "Ollama"
  step "Ollama asks to install its command line tool: accept and enter your password."
  pause "Done? Press Enter to check."
  command -v ollama >/dev/null 2>&1 && printf '  %s✓%s ollama on PATH\n' "$GREEN" "$RESET" \
    || { SKIPPED+=("Ollama CLI link (open Ollama → install command line)"); warn "ollama still not on PATH"; }
fi
pause

# ── Keyboard layouts ─────────────────────────────────────────────────────────
stage "Keyboard input sources"
say "chezmoi put lplatzer-layout in ~/Library/Keyboard Layouts."
say "macOS lists it after the re-login in the last stage; add it then."
step "After logging back in: System Settings → Keyboard → Input Sources → Edit → + → Others."
open_url "x-apple.systempreferences:com.apple.Keyboard-Settings.extension"
pause

# ── Re-login ─────────────────────────────────────────────────────────────────
stage "Log out and back in"
say "Three settings only take effect after a new login: Ctrl+Cmd drag-anywhere,"
say "one Space across all displays, and the new keyboard layouts."
if confirm "Log out now? (Save your work first.)"; then
  osascript -e 'tell application "System Events" to log out' || warn "log out from the Apple menu instead"
else
  SKIPPED+=("log out and back in (drag gesture, Spaces, keyboard layouts)")
fi

finish
}

run_wizard "$@"; exit
